              "ar": "في الأسماء المكتوبات على جبين جبرائيل عليه السلام، الواقف على شمال القدرة منتظراً ما يؤمر به من الوحي الإلهي. وهي على الملائكة المختصين باللوح المحيط بكل علم والعلم الرفيع، متى دعوتهم بها أجابوا سمعاً وطاعة لله عز وجل، وبأسمائه وبها خلقهم. وهي مكتوبة على جبين جبريل عليه السلام، وهي التي كان يتكلم بها عيسى بن مريم عليه السلام عند مهمات الأمر، وهي هذه:"
