            {
              "type": "p",
              "en": "Their interpretation in Arabic:",
              "ar": "تفسيرها بالعربية:"
            },
            {
              "type": "quote",
              "en": "Glory be to You, O You of mighty rank; glory be to You, O You eternal in beneficence; glory be to You, O You who are glorified by every tongue; glory be to You, O You who are sanctified in every place; glory be to You, O You who are worshipped in every place; glory be to You, O You who are everlasting in giving. Exalted is my Lord above what the wrongdoers say, with great exaltation.",
              "ar": "سبحانك يا عظيم الشأن، سبحانك يا قديم الإحسان، سبحانك يا مسبّح بكل لسان، سبحانك يا مقدَّس في كل مكان، سبحانك يا معبود في كل مكان، سبحانك يا دائم الإنعام، تعاليت ربي عما يقول الظالمون علواً كبيراً."
            },
            {
              "type": "p",
              "en": "Know, my brother — may God grant you success — that these noble, subtle, mighty, pure, and purified names are the ones by which Joshua son of Nun (يوشع بن نون, Yūshaʿ ibn Nūn) spoke on Tuesday, and the sun turned back for him. By them Moses (موسى, Mūsā) also spoke against Og son of Anak (عوج بن عنق, ʿŪj ibn ʿAnaq), and he was stunned until he killed him. They are an obedience over all the angels of the seventh heaven. By them he also spoke against Israel the angel (إسرائيل الملك, Isrāʾīl al-malak) when he came in to him: he seized him by his collar, spat in his mouth, and he crumbled on the spot, by God's permission.",
              "ar": "اعلم يا أخي — وفقك الله تعالى — أن هذه الأسماء الشريفة اللطيفة العظيمة الطاهرة المطهرة، هي التي تكلم بها يوشع بن نون عليه السلام يوم الثلاث، فقهقرت له الشمس. وبها أيضاً تكلم موسى عليه السلام على عوج بن عنق، فبهت حتى قتله. وهي طاعة على جميع ملائكة السماء السابعة. وبها أيضاً تكلم على إسرائيل الملك إذا دخل عليه، فمسك بطوقه، فتفل في فيه، فتهرى من حينه، بإذن الله تعالى."
            },
            {
              "type": "p",
              "en": "Through them, by God's permission, one disposes of the binding of tongues, entry upon rulers, the fulfilling of needs, the suppression of tyrants, and the burning of rebels. They are the ones entrusted with sinking and transformation, and they confound the spiritual angels who are below them. When you speak these names, sincerely, in the described condition, a flame of fire comes from your mouth and burns every spirit it meets. Beware of speaking them while one of your helpers is with you, lest you torment him. Do not speak them except in a place pure of defilement, as I have told you. The angel entrusted with them and set over them will attend you, obedient to your command in all that you desire for the pleasure of God, mighty and exalted, in obedience from him to the names of God Most High.",
              "ar": "تتصرف بإذن الله تعالى في عقد الألسن، والدخول على السلطان وقضاء الحوائج، وإقماع الجبارين وإحراق المتمردين. وهم المتوكلون بالخسف والمسخ، ويبهتون الملائكة الروحانيين الذين دونهم. إذا تكلمت بهذه الأسماء، وأنت مخلص على الهيئة الموصوفة، يخرج من فيك لهيب النار تحرق كل روح تقابله. وإياك أن تتكلم بها ومعك عون من أعوانك فتعذبه. ولا تتكلم بها إلا في موضع طاهر من الدنس، كما ذكرت لك. يحضرك الملك الموكل بهم والمقدم عليهم، ممتثلاً لأمرك في كل ما تريد من مرضاة الله عز وجل، طاعة منه لأسماء الله تعالى."
            },
            {
              "type": "p",
              "en": "If you enter upon a tyrannical, overpowering king, God will subdue him to you. If you call by them a king from the kings of the jinn, he will come at once, faster than the blink of lightning. If a helper among the helpers is unclear to you, adjure by them and say: “Bring me so-and-so” — whether he is an angel or one of the earthly spirits. Then judge him as you wish, in obedience from me to the names of God Most High. If you contend with an adversary, you will overpower him by them. They dispose, by God's permission, of everything, great and small, among works of righteousness.",
              "ar": "وإذا دخلت على ملك طاغ قاهر يقهره الله إليك. وإذا دعوت بها ملكاً من ملوك الجن، حضر في الحين والوقت، أسرع من لمح البرق. وإذا التبس عليك عون من الأعوان، فتقسم بها وتقول: عليّ بفلان، سواء كان ملكاً من الملائكة، أو من الروحانية الأرضية. فاحكم فيه بما شئت طاعة مني لأسماء الله تعالى. وإذا تنازعت مع خصم تقهره بها، وهي تتصرف بإذن الله تعالى في كل شيء من الأعمال الكبار والصغار من أعمال البر."
            }
