            {
              "type": "p",
              "en": "These are the names by which God created the people of the second heaven; by them they glorify God Most High, and they are obedient to Him and speak by them. Whenever you call them by them, they answer with hearing and obedience to God, mighty and exalted, and to His noble, mighty, glorious, pure, and holy names. Through them they dispose for you of all that you desire, in what is pleasing to God, provided you are in the described condition: good intention, belief in the good of creation, compassion for God's creatures, proclaiming the Creator's transcendence, entreating Him, seeking help from Him, and relying on Him. These are the names:",
              "ar": "وهي التي خلق الله بها أهل السماء الثانية، يسبحون الله تعالى بها فهم لها طائعون وبها يتكلمون. فمتى دعوتهم بها أجابوا سمعاً وطاعة لله عز وجل ولأسمائه الكريمة العظيمة الجليلة الزكية الطاهرة. يتصرفون لك بها في جميع ما تريده مما لله فيه رضاً، وعلى أن تكون في الهيئة الموصوفة من حسن النية واعتقاد الخير للبرية، والشفقة على خلق الله وتنزيه الباري سبحانه، والتضرع إليه والاستغاثة به والتوكل عليه. وهي هذه الأسماء:"
            },
            {
              "type": "quote",
              "en": "Yā Allāh al-ʿAzīz al-Ḥakīm, Amlī, Makhrassā, Yabkhā, Martīthā, Sakhāfīʿā, Qabīkhā, Quddūs, Quddūsā, Shalmīthā, Ḥayyūm, Qayyūmā, Ay, Ḥanānā, Ḥāʾānīyā, Quddūs, Qayyūm, Aw, Yaẓliman, Kasʿ, Salasʿ, ʿĀl, Saʿlaj, Akh, Arādūnā, Samāsmā.",
              "ar": "يا الله العزيز الحكيم أملي مخرسا يبخا مرتيثا سخافيعا قبيخا قدوس قدوسا شلميثا حيوم قيوما اي حنانا حائانيا قدوس قيوم او يظلمن كسع سلسع عال سعلج اخ ارادونا سماسما."
            },
            {
              "type": "quote",
              "en": "Glorious are Your names, holy is Your majesty, and exalted is Your mention in Your heavens and Your earth; everything in them bows to Your greatness.",
              "ar": "جلت أسماؤك وتقدس كبرياؤك وعلا ذكرك في سماواتك وأرضك وخضع كل من فيهن لعظمتك."
            },
            {
              "type": "p",
              "en": "Their interpretation in Arabic:",
              "ar": "تفسيرها بالعربية:"
            },
            {
              "type": "quote",
              "en": "Glory be to You, O Originator; glory be to You, O Restorer; glory be to You, O Possessor of the glorious Throne; glory be to You, O Possessor of the severe grasp; glory be to You, O Doer of what You will; glory be to You, O Breaker of every stubborn tyrant.",
              "ar": "سبحانك يا مبدىء، سبحانك يا معيد، سبحانك يا ذا العرش المجيد، سبحانك يا ذا البطش الشديد، سبحانك يا فعال لما تريد، سبحانك يا قاصم كل جبار عنيد."
            },
            {
              "type": "p",
              "en": "Know, my brother — may God support you — that these names are a secret among secrets. Through them one disposes, by God's permission, of works of righteousness, such as affection, the fulfilling of all needs, entry upon rulers, proposing marriage to women, and bringing down the heavenly and earthly kings. Among the wonders of their properties: if they are written on gazelle parchment or clean paper with saffron and musk dissolved in rosewater, and placed under the head, one will be informed of what will happen to him throughout his year, good or evil. If they are also written on a silver ring at one of the auspicious hours, they protect the bearer from all afflictions.",
              "ar": "اعلم يا أخي — أيدك الله — أن هذه الأسماء سر من الأسرار، تتصرف بإذن الله تعالى في أعمال البر، مثل الألفة وقضاء الحوائج كلها والدخول على السلاطين، وخطبة النساء، واستنزال الملوك الروحانية والأرضية. ومن خواص عجائبها أنها إذا كتبت في رق غزال أو ورق نقي بزعفران ومسك محلول بماء ورد، وجعلت تحت الرأس أخبر بما يجري عليه في سنته كلها من خير أو شر. وإذا كتبت أيضاً في خاتم من فضة في بعض الساعات السعيدة، حفظت حاملها من جميع الآفات."
            },
            {
              "type": "p",
              "en": "If they are written in a clean vessel, washed with pure water, and sprinkled on the face of the afflicted person, his ʿāriḍ will be burned. Also, no one speaks them in the described, pleasing manner and breathes into the face of an ʿāriḍ without him being burned.",
              "ar": "وإن كتبت في إناء نظيف وغسلتها بماء طاهر ورشيت بها وجه المصاب احترق عارضه. وأيضاً إنها ما تكلم بها متكلم على الصفة المذكورة المرضية، ونفخ في وجه عارض إلا واحترق."
            }
