              "type": "p",
              "en": "Among the luminaries he has Jupiter, and among the spiritual angels he has Sarfiyāʾīl (صرفيائيل) the King. The invocation is directed to Sarfiyāʾīl and to the people of the sixth heaven. You say:",
              "ar": "له من الدراري المشتري، وله من الملائكة الروحانيين صرفيائيل الملك. الدعوة على صرفيائيل وعلى أهل السماء السادسة، تقول:"
