              "ar": "ثكتا ثكتا اومها ثكتا وبحق الله وبعز الله وبعظمة الله وبجلال الله وبسلطان سلطان الله العجل يا زوبعة اباطل شماليك فلوش إن الذين يحادون الله ورسوله أولئك في الأذلين جهرش طش هشور يا سح ذعون شطون بعليل فيوغ مركريائيل شفليف شلفتها أجب يا زوبعة الداع بجهور ولاهور اتى بيه بيه."
