              "en": "As for what is engraved on it: with the help of God Most High you make a seal of pure white silver, on Friday and in its dignity. Then you engrave it and lift it after the engraving; then wash it with rosewater and fumigate it with aloeswood and band. You place it in a green silk pouch, then prepare yourself to stand before him. Consecrate the seal astrologically according to the consecration of seals, if God Most High wills — and He is the one whose help is sought. You engrave these names on the ring, following the bezel: Saldiyāh wa-dāʿ bism... [lacuna].",
              "ar": "وما ينقش فيه. يصنع بعون الله تعالى خاتم من فضة بيضاء نقية يوم الجمعة وفي شرفها، ثم ينقشه ويرفعه بعد النقش، وتغسله بعد ذلك بماء ورد وتبخره بعود وبند، وتجعله في كيس حرير أخضر ثم تتأهب له في الوقوف، وتنجم الخاتم على حسب تنجيم الخواتم إن شاء الله تعالى وهو المستعان، وتنقش هذه الأسماء في الحلقة تباع الفص: سلدياه وادع بسم له مج ع بج وامكرا."
