              "ar": "وهذا أجلها وأرفعها لأنه عظيم الطاعة كبير الشأن، له من الروحانية والمردة ما لا يحصي عددهم إلا الله عز وجل. يتصرف بإذن الله في جميع الأشياء المحتاج إليها، وجميع الحقائق المشار إليها، وهو خاتم الاثني عشر جنداً الذين نزلوا مع إبليس."
