              "ar": "قال معادريوس الحكيم: سألت الطباع التام عن خاتم الأقطار قال: أخبرني هرمس الكبير عن جامع الشمل يعني خاتم الاثني عشر جنداً أنه ملكه طبرين الهندي ملك الهند. وهو رجل مؤمن قال آصف ابن برخيا: طبرين ملك الهند أول من بايع سليمان بن داوود، وقد سألت أي خاتم أسهل وأفيد؟ فقالوا: عليك بخاتم الأقطار."
