              "ar": "وهو جامع الشمل الذي يطاع له جميع الملوك. فما وضعت العلماء أحسن منه، وهو خاتم معادريوس. وقد كانت الجن يأتون إلى مجلسه لأن فيه اسم الله الأعظم الذي خلق الله به الكواكب كلها."
