              "ar": "قال آصف بن برخيا: إذا أردت قتل خصم طاغ أو متمرد، فصور صورة وصور عليها مندلاً دائماً وأخرج يديها من المندل، واكتب هذه الأسماء في بطنها واحكم بما شئت. فإن غرزت في بطن الصورة شيئاً غرز في بطن ذلك المتمرد، وهي: طيطلهوش هشر مليع نقفن طهطليوش ططرش هكع هيع طليخ طفطيخ."
