              "ar": "فإذا أردت ذلك، تنقش خاتماً من نحاس أحمر يوم الثلاثاء بطالع الجدي ساعة المريخ، أول جمعة من الشهر العربي، فإذا كمل نقشه وغسلته بماء وملح، فاصنع له كيساً أحمر وتنجمه على حسب تنجيم الخواتم. وهذه صفته كما ترى:"
