              "ar": "تقول: أجب يا خندش وأنت يا نيكل، وتنادي بأسماء الأعوان. تقول: أجب يا نجاح وأنت يا أفلح وأنت يا أبا الأخوص. وهذا الكلام عليه، تقول:"
