              "ar": "قال آصف: وإذا دخلت على مصاب ومعك جماعة من العلماء، وأردت أن يحجب عنهم العارض فلا يستطيع أحد منهم على صرعه ولا على استنزال شيء، فاكتب على خوصة من النخل أو على حاشية حرير أو سكين، وتتكلم بها فترى عجباً، وهي هذه:"
