          "id": "tablet-of-solomon",
          "title": "Chapter: The Explanation of the Tablet",
          "title_ar": "فصل نذكر فيه شرح البلاطة",
          "pages": [
            84,
            85
          ],
          "blocks": [
            {
              "type": "h3",
              "en": "Chapter: The Explanation of the Tablet",
              "ar": "فصل نذكر فيه شرح البلاطة"
            },
            {
              "type": "p",
              "en": "It is the tablet that was before Solomon son of David (سليمان بن داوود, Sulaymān ibn Dāwūd), that is, the great temple on which he made covenant with the spirits, and upon which Jibrīl (جبريل), Mīkāʾīl (ميكائيل), Isrāfīl (إسرافيل) and ʿAzrāʾīl (عزرائيل) sat on the day he made covenant with the spirits.",
              "ar": "وهي البلاطة التي كانت بين يدي سليمان بن داوود، وهو الهيكل العظيم الذي عاهد عليه الأرواح، والتي قعد عليها جبريل وميكائيل وإسرافيل وعزرائيل يوم عاهد الأرواح."
            },
            {
              "type": "p",
              "en": "Aṣif son of Barakhiya (آصف بن برخيا, Āṣif ibn Barakhiyā) said: These names descended upon Solomon son of David in the Rūbānī tongue [uncertain], which the diviners of the jinn and humankind are incapable of, and the jinn bear from them a great matter. When he wished to kill a rebellious ifrit, he would spread it out, and everyone around him — human, jinn and bird — would tremble; the spiritual angels escort it on your right and on your left. Do not bring it out except under compulsion, and do not hasten to dismiss it, lest you harm yourself, for twelve kings of the angels serve it. It is the one concerning which Ibn Bāʿūrā the Persian mentioned that it was in the banner of Solomon son of David; when the wind fell still he would spread it, and the wind would blow in every place he wished.",
              "ar": "قال آصف بن برخيا: نزلت هذه الأسماء على سليمان بن داوود باللسان الرؤباني تعجز عنها كهان الجن والإنس، وتحمل منها الجن أمراً عظيماً. فكان إذا أراد قتل عفريت طاغ بسطها، فيرعد كل من حوله من الإنس والجن والطير، تزفها الملائكة الروحانيون عن يمينك ويسارك. ولا تخرجها إلا عند الكره، ولا تسرع في صرفها فتؤذي نفسك، فإنه يخدمها اثنا عشر ملكاً من الملائكة، وهي التي ذكر فيها ابن باعورا الفارسي أنها كانت في لواء سليمان بن داود، فكان إذا خمدت الريح نشرها فتهب الريح في كل مكان يريده."
            },
            {
              "type": "p",
              "en": "Aṣif son of Barakhiya said: If you wish to make it, you place it in a piece of red or white silk, and set it in a staff of hawthorn, or of pomegranate, or of quince, and spread it out; you will see the wonder. If it is night, light seven candles beneath it and pitch seven tents over it, and place in each tent a banner in the form of its owner. If it is day, do that in a place secluded from people, and light nothing. It should be far from inhabited buildings, and the place should be pure and clean, and the clothes should be worn in purity. When you make it, there should be before you a platform raised above the ground on four legs, likewise.",
              "ar": "قال آصف بن برخيا: إذا أردت صنعها تضعها في خرقة حرير حمراء أو بيضاء، وتجعلها في عصاً من عوسج أو من رمان أو من سفرجل، وانشرها تر العجب. فإن كان ليلاً فقد تحتها سبع شمعات واضرب عليها سبعة أخبية، واجعل في كل خباء لواء على شكل صاحبه. وإن كان في النهار، فاجعل ذلك في مكان منعزل عن الناس، ولا تقد شيئاً. ويكون بعيداً عن العمارة، ويكون الموضع طاهراً نقياً، وتكون الثياب على طهارة. وإن صنعتها يكون أمامك بساط مرتفع عن الأرض على أربع قوائم كذلك."
            }
          ],
