              "type": "p",
              "en": "These names are the names of the ifrits who walk beneath the tablet. They are: al-Mudhhib (المذهب), Yazīd ibn al-Ḥakīm (يزيد بن الحكيم), ʿUmar ibn Jābir (عمر بن جابر), Fīqaṭūsh (فيقطوش), Marqīl (مرقيل), Abū Maʿshar (أبو معشر), Abū al-Rahb (أبو الرهب), Abū al-Ḥakam (أبو الحكم), ʿAbd al-Raḥmān al-Mukhaṭṭab (عبد الرحمن المخطب), al-Hamīl al-Ṭayyār al-Khafī (الهميل الطيار الخفي), Abū al-Hawl (أبو الهول), ʿĀṣif al-Riyāḥ (عاصف الرياح), Ṣakhr (صخر), Shamradal al-Ṭayyār (شمردل الطيار), Khindish (خندش), Nīkal (نيكل), Shamhūrash (شمهورش), Barqān (برقان), Zawbaʿah (زوبعة), Maymūn al-Saḥābī (ميمون السحابي), Maymūn al-Ghamāmī (ميمون الغمامي), Maymūn al-Kanāwī (ميمون الكناوي), Samlaq al-Ṭayyār (سملق الطيار), al-ʿImlāq (العملاق). These are the ones who walk beneath the tablet, and they are twenty-four ifrits.",
              "ar": "وهذه الأسماء هي أسماء العفاريت الذين يمشون تحت البلاطة، وهم المذهب ويزيد بن الحكيم وعمر بن جابر وفيقطوش ومرقيل وأبو معشر وأبو الرهب وأبو الحكم وعبد الرحمن المخطب والهميل الطيار الخفي وأبو الهول وعاصف الرياح وصخر وشمردل الطيار وخندش ونيكل وشمهورش وبرقان وزوبعة وميمون السحابي وميمون الغمامي وميمون الكناوي وسملق الطيار والعملاق، فهؤلاء الذين يمشون تحت البلاطة وهم أربعة وعشرون عفريتاً."
