              "ar": "قال آصف بن برخيا: هذه صفة صرع سليمان، الذي كان يصرع به جميع الأرواح. فإذا أردت التخفيف في الاختصار، فاكتب هذه الأسماء في كف المصاب، وتأمره أن ينظر في كفه فإنه ينصرع أشد الصرع. وهو المعروف بصرع الاخطقصناه، وتتكلم به على المصاب أيضاً، وهو هذا:"
