              "ar": "يهليوه كركياط هيور كشيرياوب اهمليم شعيهوش حواليم عبدليم قشرين طوشليم طوشال علشاقش مهراقيش طقلا عقيل هيبد رشوا شقيم رفوش دقياشيم سراخيل دماقير دهيول هو هوصيا قوش مريوش قيوش مارش عفكل شيكل شهاطش يكلاوش كل وش ديوش برجاريش جهه صفيه جودرة مره بيويه دراش دمهالاجش طروش كروش حيوم قيوم الهاً رباً قديساً"
