              "ar": "ابا الاها بشعياذ يورطالش مهراقش ميخا بطهيش طلش درعاش عشقش ترتيب مراتيل برهيود رقايل برقيل واش لماش طقياش طيمروش هارش لاوش فصص حبرنب هواطيل كلكنوش رهوش اركيوش دالش عولش وارياش بهاش عوش يا عاش يا راش واش واراش وراش بنوش نوش صرصرجيا يبرشوش برنيوش دهيوش رذب عيانق مهوارش بهوارش ديوه يوه ماه يولخ"
