            {
              "type": "quote",
              "en": "O Allah, by Your most high names and Your greatest words with which You said to all things, “Be,” and it was — whatever You willed to be — drive away from us famine and pestilence; surely You are powerful over all things.",
              "ar": "اللهم بأسمائك العليا وكلماتك العظمى التي قلت بها لجميع الأشياء كن فكان ما شئت أن يكون، اطرد عنا الغلاء والوباء إنك على كل شيء قدير."
            }
