              "type": "p",
              "en": "Know that each of these names has an operation and angels set over the fulfilment of needs. If you wish to work with it in what pertains to the spiritual beings dwelling in the earth, recite the name and say: “O noble angels, by the right of these great names, command the spirit So-and-so to do such and such.” He will do what you wish, and these operations are not completed for you except by this method.",
              "ar": "اعلم أن لكل اسم من هذه الأسماء تصريفاً وملائكة موكلين بقضاء الحوائج. فإذا أردت العمل بها فيما يختص بالروحانية الساكنة في الأرض، فاتل الاسم وقل: أيتها الملائكة الكرام بحق هذه الأسماء العظام إلا ما أمرتم الروح فلاناً يفعل كذا وكذا. فإنه يفعل ما تريد ولا تتم لك هذه التصاريف إلا بهذه الطريقة."
