          "blocks": [
            {
              "type": "h3",
              "en": "The Forms of the Seven Days",
              "ar": "أشكال الأيام السبعة"
            },
            {
              "type": "p",
              "en": "It is written on paper on Sunday for روقيائيل (Rūqyāʾīl): [sigil].",
              "ar": "يكتب في الورق يوم الأحد لروقيائيل [طلسم]."
            },
            {
              "type": "p",
              "en": "It is written on paper on Monday for جبرائيل (Jibrāʾīl): [sigil].",
              "ar": "يكتب في الورق يوم الاثنين لجبرائيل [طلسم]."
            },
            {
              "type": "p",
              "en": "It is written on paper on Tuesday for سمسمائيل (Samsamāʾīl): [sigil].",
              "ar": "يكتب في الورق يوم الثلاثاء لسمسمائيل [طلسم]."
            },
            {
              "type": "p",
              "en": "It is written on paper on Wednesday for ميكائيل (Mīkāʾīl): [sigil].",
              "ar": "يكتب في الورق يوم الأربعاء لميكائيل [طلسم]."
            },
            {
              "type": "p",
              "en": "It is written on paper on Thursday for روقيائيل (Rūqyāʾīl): [sigil].",
              "ar": "يكتب في الورق يوم الخميس لروقيائيل [طلسم]."
            },
            {
              "type": "note",
              "en": "[The name is printed روقيائيل, as on Sunday; elsewhere the angel of Thursday is صرفيائيل (Sarfiyāʾīl). The name has been left as printed.]"
            },
            {
              "type": "p",
              "en": "It is written on paper on Friday for عينيائيل (ʿAniyāʾīl): [sigil].",
              "ar": "يكتب في الورق يوم الجمعة لعنيائيل [طلسم]."
            },
            {
              "type": "p",
              "en": "It is written on paper on Saturday for كسفيائيل (Kasfiyāʾīl): [sigil].",
              "ar": "يكتب في الورق يوم السبت لكسفيائيل [طلسم]."
            },
            {
              "type": "h3",
              "en": "Their Explanation",
              "ar": "شرحها"
            },
            {
              "type": "p",
              "en": "The first: you make it of sandarac and male frankincense in the form of a figure of whomever you wish; you write on the figure the forms that belong to it, and it is to be hollow. You write the names on pure parchment with saffron, musk, and rosewater, and place it inside it. You adjure over it and over the spiritual being by the name, and you write the name of the person mentioned on its right leg and your own name on its heart. It is for entering upon the sultan, for the accomplishment of needs, and for burning; and it is for all the jinn, the earth, and the regions.",
              "ar": "شرحها: الأول تصنعه من سندروس ولبان ذكر على هيئة صورة من شئت، وتكتب في الصورة ما لها من الأشكال، وتكون مجوفة، وتكتب الأسماء في رق نقي بزعفران ومسك وماء ورد، وتجعله في جوفها وتقسم عليها وعلى الروحاني بالاسم، وتكتب اسم المذكور في رجله الأيمن واسمك على قلبه. وهو للدخول على السلطان وقضاء الحوائج والإحراق، ولكافة الجان والأرض والأقاليم."
            },
            {
              "type": "p",
              "en": "The second: of silver; it is for entering upon the sultan and the emirs and for the accomplishment of a need.",
              "ar": "الثاني: من فضة، وهو للدخول على السلطان والأمراء ولقضاء الحاجة."
            },
            {
              "type": "p",
              "en": "The third: for the spellbound.",
              "ar": "الثالث: للمعقود."
            },
            {
              "type": "p",
              "en": "The fourth: made of white wax, for love, affection, and the accomplishment of needs.",
              "ar": "الرابع: يصنع من شمع أبيض للمحبة والألفة وقضاء الحوائج."
            },
            {
              "type": "p",
              "en": "The fifth: for drawing spirits out of bodies and for bringing back the absent.",
              "ar": "الخامس: في استخراج الأرواح من الأجساد ورد الغائب."
            },
            {
              "type": "p",
              "en": "The sixth: of red copper, for striking So-and-so, restraining him, subduing him, and killing him; it operates in veils against fright and panic, and in holding back venomous creatures.",
              "ar": "السادس: يكون من نحاس أحمر لضرب فلان وزجره وقهره وقتله، ويتصرف في الحجب من الفزع والجزع وفي مسك الهوام."
            },
            {
              "type": "p",
              "en": "The seventh: of white wax; the forms are engraved inside the figure, and the names are distributed over its body. Wherever there is wind in the body, pierce [the figure] at the place where the wind is, and he will be cured. Make a wick of lily oil or ben oil, and let the burning be from the side of the head. The names of killing are the seven secrets. Summon down over every king with his spiritual being in his time and his hour, and do not summon down over him without a spiritual being; know that.",
              "ar": "السابع: من شمع أبيض وتنقش الأشكال في جوف الصورة، والأسماء مفرقة على جسده وأي موضع كان في الجسم ريح، فاغرز في أي موضع يكون فيه الريح يبرأ. وتصنع فتلة من دهن زنبق أو دهن بان، ويكون الحرق من ناحية الرأس، وأسماء القتل هم الأسرار السبعة. واستنزل على كل ملك بروحانيته في وقته وساعته، ولا تستنزل عليه بغير روحانية فاعلم ذلك."
            }
          ],
