              "ar": "وفي صباح يوم الأحد صلّ الصبح وأطلق بخورك واصرف العامر، واقرأ عدد الاسم الأول مرة واحدة، واكتبه آه إيه في خاتم الرمل بعود رمان حامض رفيع تمسكه بثلاث أصابع يدك اليمنى مثل القلم، واكتب عدد الاسم ١٣٥٤ في خاتم السر. بعد ذلك اقرأ العدد ١٣٥٤ مرة والدعوة عدد ٧ مرات. وإذا أذن الظهر فصلّها وأطلق بخورك واصرف العامر، واقرأ عدد الاسم ١٣٥٤ مرة والدعوة عدد ٧ مرات. وإذا أذن العصر فصلّها وأطلق بخورك واصرف العامر، واقرأ عدد الاسم ١٣٥٤ مرة والدعوة عدد ٧ مرات."
