              "ar": "اكتب ١٠٠ ق حروفاً صغيرة بدون طمس على قميص أبيض جديد، ثم تكتب ل م ف ق ف ن ج ل على سبعة فلقات فول ناشف، كل حرف منهم على فلقة فولة، وكل أذان تؤكل السبعة فلقات الفول وهي لابسة القميص المذكور، ينقطع النزيف."
