              "ar": "هه ٢ الطش ٢ كلموش ٢ ميططرون، انزلوا بحق هذه الأسماء واعقدوا نوم كذا وكذا حتى لا ينام ولا يغفل حتى ينام الصرصار في الحلفة والجنين في الأجساد، بحق السميع والملوك الجان ٥٠٠ مرة، وأنت واضع يدك اليسرى في أذنك اليمين."
