              "type": "p",
              "en": "Then it is encircled with the verses proper to the division, which we shall mention in another place, after writing the arhāṭ (الأرهاط) around the seal. This is the description of the seal in the form that is better with respect to works of evil; the writing is all in isolated letters.",
              "ar": "ثم يحوط بالآيات الخاصة بالفرقة، وسنذكرها في مكان آخر بعد كتابة الأرهاط حول الخاتم. وهذا صفة الخاتم بصورة أجود بالنسبة لأعمال الشر. الكتابة تكون كلها أحرفاً مفردة."
