              "type": "quote",
              "en": "They love them as they love Allah, but those who believe are stronger in love for Allah. If you had spent all that is on the earth, you could not have united their hearts; but Allah has united them. Indeed, He is Mighty, Wise. O Allah, unite the hearts of the children of Adam in love for me, and cast upon me love from You, and make me as one formed under Your eye and honoured with Allah. O Allah, make me dignified and accepted in appearance in the eyes of all who see me, so that they love me and magnify me — بادوح (Bādūḥ) twenty times, وَدُود (Wadūd) twenty times.",
              "ar": "يحبونهم كحب الله والذين آمنوا أشد حباً لله لو أنفقت ما في الأرض جميعاً ما ألّفت بين قلوبهم ولكن الله ألّف بينهم إنه عزيز حكيم. اللهم ألف قلوب أولاد آدم على محبتي وألقيت عليك محبة مني ولتصنع على عيني وكان عند الله وجيهاً. اللهم اجعلني وجيهاً مقبول الصورة في عين من يراني يحبني ويعظمي بدوح ٢٠ ودود ٢٠."
