              "type": "quote",
              "en": "In the name of Allah, the Most Merciful, the Most Compassionate. O بدوح (Bādūḥ), O possessor of victory and openings, by Your praiseworthy name, join spirit to spirit by the Prophet praised, by what the Pen wrote on the Tablet, by the ark of Noah, by the truth of the elevation of the spirit. O Allah, arouse the heart of So-and-so toward So-and-so. ... By the truth of the master ميططرون (Meṭaṭrūn) and برقان (Barqān), answer, O master قسورة (Qaswara), and O master مازر (Māzir), and O master كمطم (Kamṭam), and O master طيكل (Ṭaykal). Answer, you and your servants and helpers, by the truth of the four heads: جبرائيل (Jibrāʾīl), ميكائيل (Mīkāʾīl), إسرافيل (Isrāfīl), and عزرائيل (ʿAzrāʾīl); لكهكائيل (Lakkahkāʾīl), ميائيل (Mīyāʾīl), قيائيل (Qīyāʾīl), فيائيل (Fīyāʾīl). ‘You are good, so enter it, abiding forever.’ Hurry, hasten, this hour. May Allah bless you and grant you peace.",
              "ar": "بسم الله الرحمن الرحيم يا بدوح يا صاحب النصر والفتوح، باسمك الممدوح توفق الروح إلى الروح بالنبي الممدوح، بما كتب القلم في اللوح، بسفينة نوح، بحق ارتفاع الروح. اللهم هيج قلب كذا إلى كذا. بحق للطهطيل مهطهطيل قهطيطيل فهططيل جهلططيل لجهططيل لمقفنجل، أجلب وهيج قلب كذا إلى كذا. بحق السيد ميططرون وبرقان، أجب أيها السيد قسورة ويا سيد مازر ويا سيد كمطم ويا سيد طيكل، أجيبوا أنتم وخدامكم وأعوانكم بحق الرؤوس الأربعة: جبرائيل وميكائيل وإسرافيل وعزرائيل، لكهكائيل ميائيل قيائيل فيائيل. طبتم فادخلوها خالدين. العجل الوحا الساعة. بارك الله فيكم وعليكم."
